        requires
            self.slog.len() == LOG_SIZE,
        ensures
            result == self.is_alive_value_spec(logical as int),
            result == log_entry_alive_value(logical as int, self.slog.len() as nat),
    {
        ((logical as usize) / LOG_SIZE % 2) == 0
    }

